package com.portfolio.features.skill.entity; import com.portfolio.features.portfolio.entity.Portfolio; import jakarta.persistence.*; import java.util.*; import lombok.*; @Entity @Table(name="skills") @Getter @Setter @NoArgsConstructor public class Skill { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="portfolio_id") private Portfolio portfolio; @Column(nullable=false) private String name; private String category; private int sortOrder; }
